import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { bookingAPI, reviewAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';

const CreateReview = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { user } = useAuth();
  
  const [bookings, setBookings] = useState([]);
  const [reviewData, setReviewData] = useState({
    rating: 5,
    comment: ''
  });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!user) {
      navigate('/login');
      return;
    }
    
    fetchUserBookings();
  }, [id, user, navigate]);

  const fetchUserBookings = async () => {
    setLoading(true);
    try {
      const response = await bookingAPI.getMyBookings();
      const allBookings = response.data.bookings || [];
      
      // Filtrer : seulement les réservations TERMINÉES pour cette salle
      const completedBookings = allBookings.filter(booking => {
        const isThisRoom = booking.room_id === parseInt(id);
        const isCompleted = booking.status === 'completed';
        const hasEnded = new Date(booking.end_datetime) < new Date();
        
        return isThisRoom && (isCompleted || hasEnded);
      });
      
      setBookings(completedBookings);
      
    } catch (error) {
      console.error('Erreur:', error);
      setError('Impossible de charger vos réservations');
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e) => {
    setReviewData({
      ...reviewData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    if (bookings.length === 0) {
      setError('Aucune réservation terminée pour cette salle');
      return;
    }

    try {
      // Prendre la dernière réservation terminée
      const latestBooking = bookings[0];
      
      const payload = {
        booking_id: latestBooking.id,
        rating: parseInt(reviewData.rating),
        comment: reviewData.comment
      };

      const response = await reviewAPI.create(payload);
      
      if (response.success) {
        setSuccess('Avis publié avec succès !');
        setTimeout(() => {
          navigate(`/rooms/${id}`);
        }, 2000);
      }
    } catch (error) {
      setError(error.message || 'Erreur lors de la publication');
    }
  };

  return (
    <div className="main-content">
      <div className="card">
        <h1>📝 Laisser un avis</h1>
        <p>Partagez votre expérience</p>
      </div>

      <div className="card">
        {error && <div className="alert alert-error">{error}</div>}
        {success && <div className="alert alert-success">{success}</div>}

        {loading ? (
          <p>Chargement...</p>
        ) : bookings.length === 0 ? (
          <div>
            <h3>⏳ Pas encore de réservation terminée</h3>
            <p>Vous pourrez laisser un avis une fois votre réservation terminée.</p>
            <p>Vérifiez que :</p>
            <ul>
              <li>La date de votre réservation est passée</li>
              <li>Votre réservation était confirmée</li>
              <li>Vous n'avez pas déjà laissé un avis</li>
            </ul>
            <div style={{ display: 'flex', gap: '10px', marginTop: '20px' }}>
              <Link to={`/rooms/${id}`} className="btn btn-primary">
                Retour à la salle
              </Link>
              <Link to="/dashboard" className="btn btn-secondary">
                Mes réservations
              </Link>
            </div>
          </div>
        ) : (
          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label className="form-label">Note</label>
              <div style={{ display: 'flex', gap: '5px', margin: '10px 0' }}>
                {[1, 2, 3, 4, 5].map(star => (
                  <button
                    key={star}
                    type="button"
                    onClick={() => setReviewData({...reviewData, rating: star})}
                    style={{
                      background: 'none',
                      border: 'none',
                      fontSize: '2rem',
                      cursor: 'pointer',
                      color: reviewData.rating >= star ? '#ffc107' : '#ddd'
                    }}
                  >
                    ⭐
                  </button>
                ))}
              </div>
              <small>{reviewData.rating}/5 étoiles</small>
            </div>

            <div className="form-group">
              <label className="form-label">Commentaire</label>
              <textarea
                name="comment"
                className="form-input"
                value={reviewData.comment}
                onChange={handleChange}
                rows="4"
                placeholder="Comment était votre expérience ?"
              />
            </div>

            <div style={{ display: 'flex', gap: '10px' }}>
              <button type="submit" className="btn btn-primary">
                Publier l'avis
              </button>
              <Link to={`/rooms/${id}`} className="btn btn-secondary">
                Annuler
              </Link>
            </div>
          </form>
        )}
      </div>
    </div>
  );
};

export default CreateReview;
